<script lang="ts" setup>
import { computed, inject } from 'vue';
import { ElMessageBox, ElMessage } from 'element-plus';
import sendControlSwitch from '@/CUSTOMER/Service/sendControlSwitch';
const emit = defineEmits(['loading']);
import { useRoute } from 'vue-router';
import { $gate } from '@/CUSTOMER/provide';
import { emitter } from '@/CUSTOMER/plugins/bus';

const data = inject($gate);

const waterLevelColor = computed(() => {
  const { waterLevel, dryWaterLevel, alertWaterLevel_1 } = waterLevels.value;
  const dry = dryWaterLevel > waterLevel;
  const alert = waterLevel > alertWaterLevel_1;
  if (dry) return '#FFC000';
  if (alert) return '#F00';
  return '#81CAE0';
});

const waterLevels = computed(() => {
  const level = Math.floor(waterLevel.value);
  const dryWaterLevel = Math.floor(getValue('619') || getValue('319') || 0);
  const alertWaterLevel_1 = Math.floor(getValue('606') || getValue('306') || 0);
  const alertWaterLevel_2 = Math.floor(getValue('607') || getValue('307') || 0);
  const alertWaterLevel_3 = Math.floor(getValue('608') || getValue('308') || 0);

  return {
    waterLevel: level,
    dryWaterLevel,
    alertWaterLevel_1,
    alertWaterLevel_2,
    alertWaterLevel_3
  };

  function getValue(tag: string) {
    try {
      return data?.value?.Gate?.MapSection.PLCs.find((o) => o.Tag === tag)?.Value as number;
    } catch (error) {
      return undefined;
    }
  }
});

/** 即時壓力 */
const instantPressure = computed<number>(() => {
  try {
    return (data?.value?.Sections || [])
      .find((o) => o.SectionType === 3)
      ?.PLCs.find((o) => o.Tag === '252')?.Value as number;
  } catch (error) {
    return 0;
  }
});

/** 橡皮壩壓力改由警戒壓力進行判斷，若為 null 則由前端預設的0.18取代 */
const maxPressure = computed(() => {
  const PLCs = data?.value?.Sections.find((o) => o.SectionType === 4)?.PLCs || [];
  return PLCs.find((o) => o.Tag === '311')?.Value as number;
});

/** 壩體左右護法中 右方bar的高度顯示(壓力) */
const showDamPressureHeight = computed(() => {
  try {
    const pressure = instantPressure.value;
    const typeChk = typeof pressure === 'number' || typeof pressure === 'string';
    return showBarHeight(typeChk ? Number(pressure) : 0);
  } catch (error) {
    return 0;
  }

  function showBarHeight(n: number) {
    /** 畫面上圖片的高度 */
    const HEIGHT = 146;
    /** 壓力的最高值 */
    const MAXIUM = maxPressure.value;
    const result = parseFloat(((n / MAXIUM) * HEIGHT).toFixed());

    if (result < 10) return HEIGHT;
    else if (result > HEIGHT) return 0;
    return HEIGHT - result;
  }
});

const waterLevel = computed(() => {
  try {
    return (data?.value?.Sections || [])
      .find((o) => o.SectionType === 3)
      ?.PLCs.find((o) => o.Tag === '251')?.Value as number;
  } catch (error) {
    return 0;
  }
});

const waterLevel_f = computed(() => {
  const v = waterLevel.value;
  if (typeof v !== 'number') return '-';
  return v;
});

/** 顯示水位，這邊要注意的是，高度是由上往下成長，因此這邊會用反向的方式取得值 */
function showWaterLevel(n: number, HEIGHT = 375) {
  /** 畫面上圖片的高度 */
  /** 水位的最高值 */
  const MAXIUM = 260;
  /** 當兩個水位值都為0 需要回傳 0 以迴避 NAN */
  const result = parseFloat(((n / MAXIUM) * HEIGHT).toFixed());

  if (result < 10) return HEIGHT;
  else if (result > HEIGHT) return 0;
  return HEIGHT - result;
}

/** 計算水壩高度 */
const damPercent = computed(() => {
  return showPercent(instantPressure.value);

  /** 依照橡皮壩壓力給予高度調整 */
  function showPercent(n?: string | boolean | number | null) {
    if (!n || (typeof n !== 'number' && typeof n !== 'string')) return 0.1;
    const MAXIUM = maxPressure.value;
    const result = (Number(n) / MAXIUM).toFixed(1);
    if (parseFloat(result) < 0.1) return 0.1;
    else if (parseFloat(result) > 1) return 1;
    return result;
  }
});

const damStatus = computed(() => {
  return {
    isDown: getBoolean('903'),
    isUp: getBoolean('901'),
    isDowning: getBoolean('904'),
    isUping: getBoolean('902'),
    isWorking: getBoolean('412')
  };
});

const showDamStatus = computed(() => {
  const st = damStatus.value;
  if (st.isUp) return '起立完成';
  if (st.isDown) return '倒伏完成';
  if (st.isUping) return '起立中';
  if (st.isDowning) return '倒伏中';
  if (st.isWorking) return '動作中';
  return '';
});

/** 檢查回傳的值，非 boolean 者，一律回傳 false */
const chkBooleanValue = (v: string | boolean | undefined) => {
  if (typeof v !== 'boolean') return false;
  return v;
};

const checkExists = (tag: string) => {
  const value = data?.value?.Gate?.MapSection.PLCs.find((o) => o.Tag === tag)?.Value;
  return typeof value === 'boolean';
};

const getBoolean = (tag: string) => {
  try {
    const boolean = data?.value?.Gate?.MapSection.PLCs.find((o) => o.Tag === tag)?.Value as boolean;
    return chkBooleanValue(boolean);
  } catch (error) {
    return false;
  }
};

/** 取得負面狀態 */
const getDebuff = (tag: string) => {
  try {
    const boolean = (data?.value?.Sections || [])
      .find((o) => o.SectionType === 5)
      ?.PLCs.find((o) => o.Tag === tag)?.Value as boolean;
    return chkBooleanValue(boolean);
  } catch (error) {
    return false;
  }
};

/** 取得設備狀態 */
const getDeviceStatus = (tag: string) => {
  try {
    const boolean = (data?.value?.Sections || [])
      .find((o) => o.SectionType === 6)
      ?.PLCs.find((o) => o.Tag === tag)?.Value as boolean;
    return chkBooleanValue(boolean);
  } catch (error) {
    return false;
  }
};

/** 鼓風機 */
const isBlowerOn = computed(() => getBoolean('412'));
const isBlowerWorking = computed(() => getBoolean('412'));
const isBlowerError = computed(() => getDebuff('104'));
const isBlowerExists = computed(() => checkExists('412'));

/** 進氣閥 */
const isIntakeOpen = computed(() => getDeviceStatus('207') || false);
/** 進氣閥通電中 */
const isIntakeOnline = computed(() => getBoolean('401') || false);
const isIntakeError = computed(() => getDebuff('101') || false);
const isIntakeExists = computed(() => checkExists('401') && checkExists('402'));

/** 排氣閥 */
const isExhaustOpen = computed(() => getDeviceStatus('209') || false);
// 通電
const isExhaustOnline = computed(() => getBoolean('404') || false);
const isExhaustError = computed(() => getDebuff('102') || false);
const isExhaustExists = computed(() => checkExists('404') && checkExists('405'));

const changeExhaust = async () => {
  const currentValue = isExhaustOpen.value;
  /** 欲送出的狀態 */
  const targetValue = !currentValue;
  // 404開 405關
  const allTags = ['404', '405'];
  let Tag;

  if (targetValue === true) {
    Tag = '404';
  } else {
    Tag = '405';
  }
  await controlDeviceByTag(targetValue, Tag, allTags);
};

/** 排水閥 */
const isDrainOpen = computed(() => getDeviceStatus('211') || false);
// 通電
const isDrainOnline = computed(() => getBoolean('407') || false);
const isDrainError = computed(() => getDebuff('103') || false);
const changeDrain = async () => {
  const currentValue = isDrainOpen.value;
  /** 欲送出的狀態 */
  const targetValue = !currentValue;
  // 407開 408關
  const allTags = ['407', '408'];
  let Tag;

  if (targetValue === true) {
    Tag = '407';
  } else {
    Tag = '408';
  }
  await controlDeviceByTag(targetValue, Tag, allTags);
};

/** 承水桶載重 */
const isWaterBucketError = computed(() => getDebuff('175') || false);

/** 手動開關狀態 */
const isManualIntakeOn = computed(() => {
  return getBoolean('905') || false;
});

const route = useRoute();

/** 手動充氣 */
const changeManualIntake = async () => {
  const currentValue = isManualIntakeOn.value;
  /** 欲送出的狀態 */
  const targetValue = !currentValue;
  // 412 鼓風機單開關 401 進氣閥on 402 進氣閥off
  const allTags = ['412', '401', '402'];
  let openTags;

  if (targetValue === true) {
    openTags = ['412', '401'];
  } else {
    openTags = ['402'];
  }

  try {
    const code = route.params.id as string;
    const action = targetValue === true ? '啟動' : '關閉';
    await ElMessageBox.confirm(showMsg(action), {
      type: 'info',
      center: true,
      showClose: false
    });

    emit('loading', true);
    await sendControlSwitch({ code, openTags, allTags });
    ElMessage.success(`手動充氣已成功${action}`);
    emitter.emit('refreshIws');
  } catch (e) {
    if ((e as string) === 'cencel') {
      return;
    } else if (typeof e === 'string') {
      ElMessage.warning('操作失敗: ' + e);
    }
  } finally {
    emit('loading', false);
  }

  function showMsg(action: '關閉' | '啟動') {
    let msg = `請確認操作——${action}手動充氣`;
    const v = Number(instantPressure.value);
    if (action === '啟動' && v >= 0.19) msg = `目前壩體壓力為 ${v}，請確認操作`;
    return msg;
  }
};

/** 開關 */
const controlDeviceByTag = async (targetValue: boolean, openTags: string, allTags: string[]) => {
  try {
    const code = route.params.id as string;
    const action = targetValue === true ? '啟動' : '關閉';
    const device = getDevice(openTags);
    await ElMessageBox.confirm(`請確認操作——${action}${device}。`, {
      type: 'info',
      center: true,
      showClose: false
    });

    emit('loading', true);
    await sendControlSwitch({ code, openTags, allTags });
    ElMessage.success(`${device}已成功${action}`);
    emitter.emit('refreshIws');
  } catch (e) {
    if ((e as string) === 'cancel') {
      return;
    } else if (typeof e === 'string') {
      ElMessage.warning('操作失敗: ' + e);
    }
  } finally {
    emit('loading', false);
  }

  function getDevice(id: string) {
    const ids = {
      '404': '排氣閥',
      '405': '排氣閥',
      '407': '排水閥',
      '408': '排水閥'
    } as Record<string, string>;
    return ids[id];
  }
};
